CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE "User" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"role" TEXT NOT NULL CHECK("role" IN ('Customer','Tutor')),"isActive" BOOLEAN NOT NULL DEFAULT TRUE,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE "Session" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"userId" UUID NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"tokenDigest" BYTEA NOT NULL UNIQUE CHECK(octet_length("tokenDigest")=32),"csrfNonce" BYTEA NOT NULL CHECK(octet_length("csrfNonce")=32),"csrfKeyVersion" TEXT NOT NULL DEFAULT 'v1',"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),"expiresAt" TIMESTAMPTZ NOT NULL,"revokedAt" TIMESTAMPTZ, CHECK("expiresAt">"createdAt"));
CREATE INDEX "Session_userId_idx" ON "Session"("userId");
CREATE TABLE "AuthAttemptBucket" ("kind" TEXT NOT NULL CHECK("kind" IN ('account','ip')),"keyDigest" BYTEA NOT NULL CHECK(octet_length("keyDigest")=32),"windowStart" TIMESTAMPTZ NOT NULL,"failed" INT NOT NULL DEFAULT 0 CHECK("failed">=0),"inFlight" INT NOT NULL DEFAULT 0 CHECK("inFlight">=0),"attempts" INT NOT NULL DEFAULT 0 CHECK("attempts">=0),PRIMARY KEY("kind","keyDigest","windowStart"));
CREATE TABLE "AuthAttemptReservation" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"accountKeyDigest" BYTEA NOT NULL CHECK(octet_length("accountKeyDigest")=32),"ipKeyDigest" BYTEA NOT NULL CHECK(octet_length("ipKeyDigest")=32),"windowStart" TIMESTAMPTZ NOT NULL,"state" TEXT NOT NULL DEFAULT 'pending' CHECK("state" IN ('pending','failed','success','abandoned')),"leaseUntil" TIMESTAMPTZ NOT NULL,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),"settledAt" TIMESTAMPTZ);
CREATE INDEX "AuthAttemptReservation_pending_idx" ON "AuthAttemptReservation"("state","leaseUntil");
